library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity rom_instructions is
  port (
    address : in  std_logic_vector(4 downto 0);
    clock   : in  std_logic := '1';
    q       : out std_logic_vector(7 downto 0)
  );
end rom_instructions;

architecture rtl of rom_instructions is
  type rom_array_t is array (0 to 31) of std_logic_vector(7 downto 0);

  constant MEM : rom_array_t := (
    0      => "00000000", -- play once
    1      => "00100000", -- play repeating
    2      => "11000000", -- stop
    3      => "00100000", -- play repeating
    4      => "01000000", -- pause
    5      => "00000000", -- play once
    6      => "10010000", -- seek half way
    7      => "00000000", -- play once
    8      => "11000000", -- stop
    9      => "00000000", -- play once
    others => "00000000"
  );
begin
  process (clock)
  begin
    if rising_edge(clock) then
      q <= MEM(to_integer(unsigned(address)));
    end if;
  end process;
end rtl;

